import {
  type CSSProperties,
  type KeyboardEvent,
  type PointerEvent as ReactPointerEvent,
  type ReactNode,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";
import { usePrefersReducedMotion } from "../../motion/usePrefersReducedMotion";
import "./turn-card.css";

export interface TurnCardProps {
  /** 正面。 */
  front: ReactNode;
  /** 背面。 */
  back: ReactNode;
  /** 受控：现在哪面朝外由外面说了算（复习卡就是这么用的，翻面走同一个开关）。 */
  flipped?: boolean;
  defaultFlipped?: boolean;
  onFlipChange?: (flipped: boolean) => void;
  /** 点一下自己翻。外面接管了翻面（flipOnClick={false}）就关掉。 */
  flipOnClick?: boolean;
  /** 拖着翻：手划过去纸跟着转，松手按划的方向和快慢定下来。 */
  draggable?: boolean;
  /** 指针在卡上走的时候歪一点，像被人捏在手里。 */
  tilt?: boolean;
  tiltMax?: number;
  /** 一层跟着手指走的高光。 */
  glare?: boolean;
  glareOpacity?: number;
  /** 指针停在卡上时稍稍抬起来。 */
  hoverScale?: number;
  /** 相机距离。 */
  perspective?: number;
  width?: number;
  height?: number;
  radius?: number;
  background?: string;
  color?: string;
  shadow?: boolean;
  shadowColor?: string;
  shadowOpacity?: number;
  disabled?: boolean;
  ariaLabel?: string;
  className?: string;
}

/** 手指真挪开这么多才算「在拖着翻」，再小就是点了一下。 */
const SLOP_FINE = 5;
const SLOP_COARSE = 9;
/** 松手时手上的速度（度/秒）乘上它补到目标角上 —— 甩一下也能翻过去。 */
const FLING = 0.16;
/** 快慢就看最近这一小段手走了多远。 */
const HISTORY_MS = 90;

const clamp = (value: number, low: number, high: number) =>
  Math.min(high, Math.max(low, value));
/** 离它最近的那个「摆正」角（0 / ±180 / ±360…）。 */
const snap = (deg: number) => Math.round(deg / 180) * 180;
/** 这个角上，露出的是背面吗。 */
const isBack = (deg: number) => Math.abs(Math.round(deg / 180)) % 2 === 1;

interface Grip {
  pointerId: number;
  startX: number;
  startY: number;
  /** 手接过来那一刻转到哪儿了。 */
  base: number;
  moved: boolean;
  captured: boolean;
  slop: number;
  history: Array<{ t: number; deg: number }>;
}

/**
 * 一张会翻面的卡：正面朝外时看见正面，翻过去是背面，中间那一下能看见纸
 * 侧过去的窄边。
 *
 * 角度只有一个数（deg），写在 CSS 变量 --turn 上；过渡交给 CSS，所以
 * 翻面、被手拖着转、松手弹回去走的是同一条路。手拖的那一段逐帧写变量
 * （挂上 is-dragging 把过渡关掉），松手时再交给过渡把最后半圈走完。
 *
 * 高光、倾斜同样是变量：指针在哪、光就在哪，卡面跟着歪一点。
 */
export function TurnCard({
  front,
  back,
  flipped,
  defaultFlipped = false,
  onFlipChange,
  flipOnClick = true,
  draggable = true,
  tilt = true,
  tiltMax = 12,
  glare = true,
  glareOpacity = 0.22,
  hoverScale = 1.03,
  perspective = 1100,
  width = 300,
  height = 400,
  radius = 22,
  background = "#27272a",
  color = "#f5f5f5",
  shadow = true,
  shadowColor = "#000000",
  shadowOpacity = 0.45,
  disabled = false,
  ariaLabel = "会翻面的卡",
  className = "",
}: TurnCardProps) {
  const reduce = usePrefersReducedMotion();
  const controlled = flipped !== undefined;
  const [inner, setInner] = useState(defaultFlipped);
  const shown = controlled ? Boolean(flipped) : inner;
  /** 同一个值还留一份在手边：指针回调里读到的 state 可能还是上一次渲染的。 */
  const shownRef = useRef(shown);
  shownRef.current = shown;
  const [dragging, setDragging] = useState(false);

  const rootRef = useRef<HTMLDivElement | null>(null);
  const rotorRef = useRef<HTMLDivElement | null>(null);
  /** 现在转到哪儿了（deg）。拖动的起点、松手的目标都从这儿算。 */
  const angleRef = useRef(shown ? 180 : 0);
  const gripRef = useRef<Grip | null>(null);
  /** 拖过的这一下要吞掉跟着来的 click。 */
  const draggedRef = useRef(false);

  const setVar = useCallback((name: string, value: string) => {
    rootRef.current?.style.setProperty(name, value);
  }, []);

  /** 把卡转到 deg：只写变量，怎么走过来是 CSS 的事。 */
  const paint = useCallback(
    (deg: number) => {
      rotorRef.current?.style.setProperty("--turn", `${deg.toFixed(2)}deg`);
      // 侧过来的角度上，影子跟着收窄、变淡 —— 越接近立起来越像纸。
      const facing = Math.abs(Math.cos((deg * Math.PI) / 180));
      setVar("--facing", facing.toFixed(3));
      angleRef.current = deg;
    },
    [setVar],
  );

  /** 现在真的转到哪儿了：从矩阵里反解出来，半路接手才能接着转。 */
  const liveAngle = useCallback(() => {
    const rotor = rotorRef.current;
    if (!rotor) return angleRef.current;
    const computed = getComputedStyle(rotor).transform;
    if (!computed || computed === "none") return angleRef.current;
    const matrix = new DOMMatrixReadOnly(computed);
    // rotateY 的角在 m11 = cos、m13 = -sin 上。
    const deg = (Math.atan2(-matrix.m13, matrix.m11) * 180) / Math.PI;
    return Number.isFinite(deg) ? deg : angleRef.current;
  }, []);

  /** 换一面。受控的时候只把意思告诉外面，翻不翻由 prop 说了算。 */
  const requestFlip = useCallback(
    (next: boolean) => {
      if (next === shownRef.current) return;
      if (!controlled) setInner(next);
      onFlipChange?.(next);
    },
    [controlled, onFlipChange],
  );

  // 哪面朝外（不管是谁决定的）→ 转到那个角。
  useEffect(() => {
    paint(shown ? 180 : 0);
  }, [paint, shown]);

  const restPose = useCallback(() => {
    setVar("--tilt-x", "0deg");
    setVar("--tilt-y", "0deg");
    setVar("--sheen", "0");
    setVar("--lift", "1");
  }, [setVar]);

  useEffect(() => {
    if (disabled) restPose();
  }, [disabled, restPose]);

  // 手在卡外面松开的情况：鼠标按下后轻轻滑出卡外（没到算拖的那点距离，
  // 所以还没接过指针）再松开，pointerup 就落不到卡身上。留着这一握不放，
  // 下一回按下去会被当成「上一下还没松」，起手就少一段 slop。
  // 挂二层（冒泡最外层）：卡自己的 pointerup 先跑，跑完了这儿再看有没有剩。
  useEffect(() => {
    const sweep = (event: PointerEvent) => {
      const grip = gripRef.current;
      if (!grip || grip.pointerId !== event.pointerId) return;
      gripRef.current = null;
      if (grip.moved) setDragging(false);
    };
    window.addEventListener("pointerup", sweep);
    window.addEventListener("pointercancel", sweep);
    return () => {
      window.removeEventListener("pointerup", sweep);
      window.removeEventListener("pointercancel", sweep);
    };
  }, []);

  const handlePointerDown = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      // 用键盘翻过一张之后（空格、回车 —— 卡上就写着这行提示），浏览器会把这
      // 圈焦点环一直挂在卡上，连之后拿鼠标点它都照旧亮着，看着像卡片自己多了
      // 一道边框。指针一碰先让掉：紧接着 mousedown 会拿「鼠标」的名义把它重新
      // 聚焦一次，环就不亮了；键盘用户 Tab 过来时它照样在，那是他们唯一的定位
      // 线索，不能一并抹掉。
      if (rootRef.current && rootRef.current === document.activeElement) {
        rootRef.current.blur();
      }
      if (disabled || event.button !== 0 || gripRef.current) return;
      // 这里先不 capture：一按下就接过来，点卡片里那些按钮（收藏、掌握、
      // 删除）松手那下 click 会被重定到卡片上，按钮就点不着了。真挪起来再接。
      draggedRef.current = false;
      gripRef.current = {
        pointerId: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        base: liveAngle(),
        moved: false,
        captured: false,
        slop: event.pointerType === "touch" ? SLOP_COARSE : SLOP_FINE,
        history: [],
      };
      if (!reduce) setVar("--lift", String(hoverScale));
    },
    [disabled, hoverScale, liveAngle, reduce, setVar],
  );

  const handlePointerMove = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      const grip = gripRef.current;
      if (grip && grip.pointerId === event.pointerId) {
        const dx = event.clientX - grip.startX;
        const dy = event.clientY - grip.startY;
        if (!grip.moved) {
          if (!draggable || reduce) return;
          if (Math.abs(dx) < grip.slop && Math.abs(dy) < grip.slop) return;
          grip.moved = true;
          draggedRef.current = true;
          setDragging(true);
          // 拖起来就不歪了：这时候手在转纸，不是在摸卡面。
          setVar("--tilt-x", "0deg");
          setVar("--tilt-y", "0deg");
          setVar("--sheen", "0");
          try {
            event.currentTarget.setPointerCapture(event.pointerId);
            grip.captured = true;
          } catch {
            /* 拿不到就算了，事件照样来。 */
          }
          // 到这一刻过渡已经往前跑了一段，从眼下这个角接手。
          grip.base = liveAngle();
        }
        // 划过一个卡宽差不多就是半圈。
        const span = typeof width === "number" && width > 0 ? width : 300;
        const deg = grip.base + (dx / span) * 180;
        paint(deg);
        const now = performance.now();
        grip.history.push({ t: now, deg });
        // 只留最近这一小段：松手时看这一段走了多远，就知道手甩得多快。
        while (grip.history.length > 2 && now - (grip.history[0]?.t ?? now) > HISTORY_MS) {
          grip.history.shift();
        }
        return;
      }
      if (!tilt || reduce || disabled || event.pointerType === "touch") return;
      const rect = event.currentTarget.getBoundingClientRect();
      const px = clamp((event.clientX - rect.left) / rect.width, 0, 1);
      const py = clamp((event.clientY - rect.top) / rect.height, 0, 1);
      setVar("--tilt-x", `${((0.5 - py) * 2 * tiltMax).toFixed(2)}deg`);
      setVar("--tilt-y", `${((px - 0.5) * 2 * tiltMax).toFixed(2)}deg`);
      setVar("--sheen", "1");
      setVar("--glare-x", `${(px * 100).toFixed(1)}%`);
      setVar("--glare-y", `${(py * 100).toFixed(1)}%`);
    },
    [disabled, draggable, liveAngle, paint, reduce, setVar, tilt, tiltMax, width],
  );

  const endGrip = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>, cancelled: boolean) => {
      const grip = gripRef.current;
      if (!grip || grip.pointerId !== event.pointerId) return;
      gripRef.current = null;
      if (grip.captured) {
        try {
          event.currentTarget.releasePointerCapture(event.pointerId);
        } catch {
          /* 已经自己放掉了。 */
        }
      }
      if (grip.moved) setDragging(false);
      if (event.pointerType === "touch" || !rootRef.current?.matches(":hover")) {
        restPose();
      }

      if (!grip.moved) {
        // 没挪动：这一下是点。但翻面不在这儿做 —— 松手之后还会跟来一个 click，
        // 那一个才是翻面的入口（键盘、读屏走的也是它）。在这儿先翻一次的话，
        // click 接着看到的就是翻过之后的值，一翻一翻又回到原地，等于白点。
        if (cancelled) paint(shownRef.current ? 180 : 0);
        return;
      }

      const here = angleRef.current;
      let velocity = 0;
      const first = grip.history[0];
      const last = grip.history[grip.history.length - 1];
      if (!cancelled && first && last && last.t > first.t && performance.now() - last.t < 60) {
        velocity = ((last.deg - first.deg) / (last.t - first.t)) * 1000;
      }
      const settled = snap(here);
      // 往哪边甩、甩多快，最远也就是跨过一整面 —— 不许一把划过两张。
      const target = cancelled
        ? snap(grip.base)
        : clamp(snap(here + velocity * FLING), settled - 180, settled + 180);
      paint(target);
      requestFlip(isBack(target));
    },
    [paint, requestFlip, restPose],
  );

  const handleKeyDown = useCallback(
    (event: KeyboardEvent<HTMLDivElement>) => {
      if (disabled || (event.key !== "Enter" && event.key !== " ")) return;
      event.preventDefault();
      if (event.repeat) return;
      requestFlip(!shownRef.current);
    },
    [disabled, requestFlip],
  );

  return (
    <div
      ref={rootRef}
      role="button"
      tabIndex={disabled ? -1 : 0}
      aria-pressed={shown}
      aria-disabled={disabled || undefined}
      aria-label={ariaLabel}
      className={[
        "turn-card",
        dragging && "is-dragging",
        reduce && "is-static",
      ]
        .filter(Boolean)
        .join(" ")
        .concat(className ? ` ${className}` : "")}
      data-flipped={shown ? "" : undefined}
      data-draggable={draggable && !disabled && !reduce ? "" : undefined}
      data-disabled={disabled ? "" : undefined}
      style={
        {
          "--turn-card-w": `${width}px`,
          "--turn-card-h": `${height}px`,
          "--turn-card-radius": `${radius}px`,
          "--turn-card-bg": background,
          "--turn-card-ink": color,
          "--turn-card-shadow-color": shadowColor,
          "--turn-card-shadow-alpha": String(shadowOpacity),
          "--turn-card-glare-alpha": String(glareOpacity),
          "--turn-card-perspective": `${perspective}px`,
        } as CSSProperties
      }
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={(event) => endGrip(event, false)}
      onPointerCancel={(event) => endGrip(event, true)}
      onLostPointerCapture={(event) => endGrip(event, true)}
      onPointerEnter={(event) => {
        if (!reduce && !disabled && event.pointerType !== "touch") {
          setVar("--lift", String(hoverScale));
        }
      }}
      onPointerLeave={() => {
        if (!gripRef.current) restPose();
      }}
      onKeyDown={handleKeyDown}
      onClick={() => {
        // 点一下翻面走的就是这里 —— 手拖着转完那一下松开的 click 不算「点」。
        if (draggedRef.current) {
          draggedRef.current = false;
          return;
        }
        if (disabled) return;
        if (flipOnClick) requestFlip(!shownRef.current);
      }}
      onDragStart={(event) => event.preventDefault()}
      onContextMenu={(event) => event.preventDefault()}
    >
      {shadow ? <span className="turn-card__shadow" aria-hidden="true" /> : null}
      <div className="turn-card__stage">
        <div ref={rotorRef} className="turn-card__rotor">
          <div
            className="turn-card__face turn-card__face--front"
            aria-hidden={shown || undefined}
            inert={shown || undefined}
          >
            {front}
            {glare ? <span className="turn-card__glare" aria-hidden="true" /> : null}
          </div>
          <div
            className="turn-card__face turn-card__face--back"
            aria-hidden={!shown || undefined}
            inert={!shown || undefined}
          >
            {back}
            {glare ? <span className="turn-card__glare" aria-hidden="true" /> : null}
          </div>
        </div>
      </div>
    </div>
  );
}

export default TurnCard;
